import java.util.*;

class Sales
{
    public static void main(String[] args)
    {
        Scanner sc = new Scanner(System.in);
        double A[][] = new double[3][4];
        int i, j;
        for (i = 0; i < 3; i++)
        {
            for (j = 0; j < 4; j++)
            {
                System.out.print("Sales of salesman " + (i + 1) + " for product " + (j + 1) + ": ");
                A[i][j] = sc.nextDouble();
            }
        }
        // total of each salesman = row sum
        for (i = 0; i < 3; i++)
        {
            double s = 0;
            for (j = 0; j < 4; j++)
                s = s + A[i][j];
            System.out.println("Total sales by salesman " + (i + 1) + " = " + s);
        }
        // total of each product = column sum
        for (j = 0; j < 4; j++)
        {
            double s = 0;
            for (i = 0; i < 3; i++)
                s = s + A[i][j];
            System.out.println("Total sales of product " + (j + 1) + " = " + s);
        }
    }
}

/* Variable description
   A    : double[3][4]  sales; row = salesman, column = product
   i, j : int           loop counters
   s    : double        running total of a row or a column  */

(Corrected: the source program adds into an undeclared s1 and has a stray line int k=i+1 in the product loop; both are fixed above.)

import java.util.*;

class CalendarPrint
{
    public static void main(String[] args)
    {
        String cal[][] = new String[6][7];
        String days[] = {"SUN", "MON", "TUE", "WED", "THUR", "FRI", "SAT"};
        int i, j, d = 1;
        for (j = 0; j < 7; j++)
            cal[0][j] = days[j];
        for (i = 1; i < 6; i++)
        {
            for (j = 0; j < 7; j++)
            {
                if (i == 1 && j < 2)
                    cal[i][j] = "-";          // blank days before the 1st
                else if (d <= 30)
                {
                    cal[i][j] = "" + d;
                    d++;
                }
                else
                    cal[i][j] = "";           // after the 30th
            }
        }
        for (i = 0; i < 6; i++)
        {
            for (j = 0; j < 7; j++)
                System.out.print(cal[i][j] + "\t");
            System.out.println();
        }
    }
}

/* Variable description
   cal  : String[6][7]  the calendar table (row 0 = day names)
   days : String[]      names of the days
   d    : int           next date to place (1 to 30)
   i, j : int           row and column counters  */

class Table
{
    public static void main(String[] args)
    {
        double table[][] = new double[8][12];
        int i, j;
        for (i = 1; i <= 8; i++)              // rows numbered 1 to 8
        {
            for (j = 1; j <= 12; j++)         // columns numbered 1 to 12
            {
                table[i - 1][j - 1] = 1.0 / (i + j - 1);
                System.out.print(table[i - 1][j - 1] + "  ");
            }
            System.out.println();
        }
    }
}

/* Variable description
   table : double[8][12]  the numeric table
   i, j  : int            row and column numbers (1-based, so i + j - 1 is never 0)  */

Note: 1.0 is used so the division is real; 1 / (i + j - 1) in int would give 0 for every element except table[1][1]. (Corrected: the source program used an int array, integer division and loops starting at index 1 that skip row 0 and column 0.)

