import java.util.*;

class ReplaceLast
{
    static String replaceWord(String input)
    {
        String s = " " + input + " ";          // pad so the first/last word also has spaces round it
        int k = s.lastIndexOf(" is ");         // spaces stop "is" inside "This" from matching
        if (k == -1)
            return input;
        s = s.substring(0, k) + " was " + s.substring(k + 4);
        return s.substring(1, s.length() - 1); // remove the padding spaces
    }

    public static void main(String[] args)
    {
        Scanner sc = new Scanner(System.in);
        System.out.println("Enter a sentence:");
        String str = sc.nextLine();
        System.out.println("Modified string: " + replaceWord(str));
    }
}

/* Variable description
   input : String  sentence passed to the method
   s     : String  padded sentence being changed
   k     : int     index where the last " is " starts
   str   : String  sentence entered  */

