import java.util.*;

class Reverse
{
    static String rev(String str, int m, int n)
    {
        String part = str.substring(m, m + n);  // n characters from index m
        String r = "";
        for (int i = part.length() - 1; i >= 0; i--)
            r = r + part.charAt(i);
        return r;
    }

    public static void main(String[] args)
    {
        Scanner sc = new Scanner(System.in);
        System.out.println("Please enter the string:");
        String nam = sc.nextLine();
        System.out.println("Position (index) to start from:");
        int pos = sc.nextInt();
        System.out.println("Number of characters:");
        int nm = sc.nextInt();
        System.out.println(rev(nam, pos, nm));
    }
}

/* Variable description
   str, nam : String  the string
   m, pos   : int     starting index
   n, nm    : int     number of characters
   part     : String  the extracted characters
   r        : String  the reversed characters
   i        : int     loop counter  */

Example: rev("COMPUTER", 2, 4) extracts "MPUT" and returns "TUPM".
(The source answer uses StringBuffer.reverse(); a loop with charAt() gives the same result using only the String class.)

