class AgeChange
{
    static String change(String str, int current)
    {
        int sp = str.indexOf(' ');                       // end of the age
        int last = str.lastIndexOf(' ');                 // start of the year
        int age = Integer.parseInt(str.substring(0, sp));
        int yr = Integer.parseInt(str.substring(last + 1));
        int newAge = age + (current - yr);
        return newAge + str.substring(sp, last + 1) + current;
    }

    public static void main(String[] args)
    {
        String s = "10 years old in the year 1960";
        System.out.println(change(s, 2005));
    }
}

/* Variable description
   str      : String  original sentence
   current  : int     current year (2005)
   sp, last : int     positions of the first and last space
   age, yr  : int     age and year in the sentence
   newAge   : int     age in the current year  */

Output: 55 years old in the year 2005   (10 + (2005 - 1960) = 55)
